def translate_review_prompt(query):
    """Strip Claude Code-only arguments from a leading /review prompt.

    Claude Code's /review is a full alias for /code-review: it takes an effort
    level plus --fix and --comment. Copilot CLI's /review takes a free-form
    prompt, so those arguments are dropped instead of being forwarded literally.
    """
    parts = query.split()
    if not parts or parts[0] != "/review":
        return query

    args = parts[1:]
    dropped = []
    # The effort level, when present, is the first argument.
    if args and args[0] in REVIEW_EFFORT_LEVELS:
        dropped.append(args.pop(0))
    kept = []
    for arg in args:
        if arg in ("--fix", "--comment"):
            dropped.append(arg)
        else:
            kept.append(arg)

    if not dropped:
        return query

