REVIEW_EFFORT_LEVELS = {"low", "medium", "high", "xhigh", "max", "ultra"}

# /code-review flags with no Copilot CLI equivalent. --post (v2.1.227+) only
# applies with 'ultra'; --max-findings takes n|all|default as its value.
REVIEW_BOOL_FLAGS = {"--fix", "--comment", "--post"}
REVIEW_VALUE_FLAGS = {"--max-findings"}


def translate_review_prompt(query):
    """Strip Claude Code-only arguments from a leading /code-review or /review prompt.

    Claude Code's /review is a full alias for /code-review: it takes an effort
    level plus --fix, --comment, --post, and --max-findings. Copilot CLI's
    /review takes a free-form prompt, so /code-review is renamed to /review and
    those arguments are dropped instead of being forwarded literally.
    """
    parts = query.split()
    if not parts or parts[0] not in ("/review", "/code-review"):
        return query

    renamed = parts[0] != "/review"
    args = parts[1:]
    dropped = []
    # The effort level, when present, is the first argument.
    if args and args[0] in REVIEW_EFFORT_LEVELS:
        dropped.append(args.pop(0))
    kept = []
    i = 0
    while i < len(args):
        arg = args[i]
        name = arg.split("=", 1)[0]
        if arg in REVIEW_BOOL_FLAGS:
            dropped.append(arg)
        elif name in REVIEW_VALUE_FLAGS:
            dropped.append(arg)
            if "=" not in arg and i + 1 < len(args) and not is_flag(args[i + 1]):
                dropped.append(args[i + 1])
                i += 1
        else:
            kept.append(arg)
        i += 1

    if not dropped:
        return " ".join(["/review"] + kept) if renamed else query

